class.description:
[method FlowGraphPlayback.get_available_exits] returns one [FlowExit] per way out of the current node, for example to build a choice menu; [method FlowGraphPlayback.choose] takes its index. Node types create their own exits in [method FlowNode._get_available_exits], for example with a label per option or with options disabled by a condition.
[codeblocks]
[gdscript]
var exits := playback.get_available_exits()
var index := 0
for exit: FlowExit in exits:
    var button := Button.new()
    button.text = exit.label
    button.disabled = not exit.enabled
    button.pressed.connect(playback.choose.bind(index))
    menu.add_child(button)
    index += 1
[/gdscript]
[csharp]
var exits = playback.GetAvailableExits();
int index = 0;
foreach (FlowExit exit in exits)
{
    int choice = index++;
    var button = new Button { Text = exit.Label, Disabled = !exit.Enabled };
    button.Pressed += () => playback.Choose(choice);
    menu.AddChild(button);
}
[/csharp]
[/codeblocks]
